/**
 * Fictitious `@deepseek-ai/dsh-credentials-local` fixture.
 *
 * It mirrors only the *public shape* dsh-locale relies on:
 * `parseCredentialsDocument(text, filename) -> { refs: Map, records: Map }`.
 * It is dependency-free (no YAML library) and deliberately understands just
 * the version-1 `refs:` subset used by the credential fixtures; anything else
 * throws. That keeps the test honest: if dsh-locale ever parsed the store
 * itself instead of calling this export, the limited fixture would fail.
 *
 * When `DSH_LOCALE_FIXTURE_PARSER_MARKER` is set, invocation drops a marker
 * file so a test can prove a dry run never resolves the stored credential.
 */

import fs from 'node:fs'

export function parseCredentialsDocument(text, filename) {
  if (process.env.DSH_LOCALE_FIXTURE_PARSER_MARKER) {
    fs.writeFileSync(process.env.DSH_LOCALE_FIXTURE_PARSER_MARKER, 'called')
  }

  const refs = new Map()
  const records = new Map()
  const lines = String(text).split('\n')
  if (!lines.some((line) => /^version:\s*1\s*$/.test(line))) {
    throw new Error(`fixture parser: unsupported credentials document ${filename}`)
  }

  let inRefs = false
  for (const line of lines) {
    if (/^refs:\s*$/.test(line)) {
      inRefs = true
      continue
    }
    if (/^\S/.test(line)) {
      inRefs = false
      continue
    }
    if (!inRefs) continue
    const match = /^\s+([A-Za-z_][A-Za-z0-9_]*):\s*(.+?)\s*$/.exec(line)
    if (match) refs.set(match[1], match[2])
  }
  return { refs, records }
}
